package com.example.starter.config;

import java.time.Clock;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * 应用基础配置：提供 UTC 时钟，便于业务与测试使用可控时间。
 */
@Configuration
public class AppConfig {

    /**
     * 业务时钟，默认 UTC 系统时钟；测试中可替换为可控时钟。
     */
    @Bean
    public Clock businessClock() {
        return Clock.systemUTC();
    }
}

package com.example.starter.domain;

/**
 * 进场批次状态。
 * REGISTERED 已报备（可抽样、可快检）；SUSPECTED 疑似超标冻结（等待定量复检）；
 * RELEASED 放行（终态）；DISPOSED 监督处置结案（终态）。
 */
public enum BatchStatus {
    REGISTERED,
    SUSPECTED,
    RELEASED,
    DISPOSED;

    /**
     * 是否为终态（放行/处置结案），终态后只允许记录迟到事件。
     */
    public boolean isTerminal() {
        return this == RELEASED || this == DISPOSED;
    }
}

package com.example.starter.domain;

/**
 * 快检判定口径：抑制率 &gt;= 50%（恰 50% 亦判疑似）判 SUSPECTED 疑似超标，否则 PASS 合格。
 */
public enum TestVerdict {
    PASS,
    SUSPECTED;

    /**
     * 按抑制率（%）判定快检结果。
     */
    public static TestVerdict of(java.math.BigDecimal inhibitionRate) {
        return inhibitionRate.compareTo(new java.math.BigDecimal("50")) >= 0 ? SUSPECTED : PASS;
    }
}

package com.example.starter.domain;

/**
 * 定量复检结果：PASS 合格放行；FAIL 不合格转监督处置并留样 48 小时。
 */
public enum RecheckResult {
    PASS,
    FAIL
}

package com.example.starter.domain;

/**
 * 抽检方式：NORMAL 常规抽检；ENHANCED 产地预警期间的逐批加严抽检。
 */
public enum SamplingMode {
    NORMAL,
    ENHANCED
}

