@Transactional
public RapidTestResponse rapidTest(long batchId, RapidTestRequest req) {
    Batch batch = find or 404;
    String fp = Fingerprints.of(req.requestId(), String.valueOf(batchId), req.item(), req.inhibitionRate().toPlainString());
    var byReq = rapidTestRepository.findByRequestId(req.requestId());
    if (byReq.isPresent()) {
        RapidTest t = byReq.get();
        if (!t.fingerprint().equals(fp)) throw new ConflictException("同一 requestId 业务参数不一致，拒绝重放");
        return RapidTestResponse.from(t, batch.status(), false, null);
    }
    LocalDateTime now = LocalDateTime.now(clock);
    if (batch.status().isTerminal()) {
        long eventId = lateEventRepository.insert(batchId, "RAPID_TEST", "结案后迟到快检结果，requestId=" + req.requestId(), now);
        return RapidTestResponse.late(batchId, batch.status());
    }
    if (batch.status() == BatchStatus.SUSPECTED) throw new ConflictException("该批次存在进行中的检测链（疑似待复检），拒绝新的快检");
    sampleRepository.findByBatchAndItem(batchId, req.item()).orElseThrow(() -> new ConflictException("未抽样不能快检：批次+项目缺少抽样记录"));
    rapidTestRepository.findByBatchAndItem(batchId, req.item()).ifPresent(t -> { throw new ConflictException("重复送检拒绝：该批次该项目已检测"); });
    TestVerdict verdict = TestVerdict.of(req.inhibitionRate());
    long testId;
    try {
        testId = rapidTestRepository.insert(req.requestId(), fp, batchId, req.item(), req.inhibitionRate(), verdict, now);
    } catch (DuplicateKeyException e) {
        throw new ConflictException("重复送检拒绝：该批次该项目已检测");
    }
    BatchStatus newStatus;
    if (verdict == SUSPECTED) {
        transition(batch, REGISTERED, SUSPECTED, now);
        alertService.onSuspected(batch, now);
        newStatus = SUSPECTED;
    } else {
        transition(batch, REGISTERED, RELEASED, now);  // 判定与放行同一事务
        newStatus = RELEASED;
    }
    return new RapidTestResponse(testId, batchId, req.item(), req.inhibitionRate(), verdict, newStatus, false, now);
}

private void transition(Batch batch, BatchStatus expected, BatchStatus target, LocalDateTime now) {
    if (batchRepository.transitionStatus(batch.id(), expected, target, now) == 0) {
        throw new ConflictException("批次状态已变更，检测链冲突");
    }
}
```

