@Transactional
public RecheckResponse recheck(long batchId, RecheckRequest req) {
    Batch batch = find or 404;
    String fp = Fingerprints.of(req.requestId(), String.valueOf(batchId), req.result().name());
    var byReq = recheckRepository.findByRequestId(req.requestId());
