        // idempotent replay — return first result with current batch status & retention
        Retention ret = retentionRepository.findByBatchId(batchId).orElse(null);
        return RecheckResponse.from(r, batch.status(), ret, false);
    }
    LocalDateTime now = LocalDateTime.now(clock);
    if (batch.status().isTerminal()) {
        lateEventRepository.insert(batchId, "RECHECK", "结案后迟到复检结果，requestId=" + req.requestId(), now);
        return RecheckResponse.late(batchId, batch.status());
    }
    if (batch.status() != SUSPECTED) throw new ConflictException("批次非疑似冻结状态，不能复检");
    long recheckId;
    try {
        recheckId = recheckRepository.insert(req.requestId(), fp, batchId, req.result(), now);
    } catch (DuplicateKeyException e) {
        throw new ConflictException("复检幂等键冲突");
    }
    if (req.result() == PASS) {
        transition SUSPECTED→RELEASED;
        return response(recheckId, RELEASED, null, false);
    } else {
        transition SUSPECTED→DISPOSED;
        LocalDateTime until = now.plusHours(48);
        retentionRepository.insert(batchId, until, now);
        return response(recheckId, DISPOSED, until, false);
    }
}
