        assertThat(rapidTestRepository.count()).isEqualTo(1);
        assertThat(batchRepository.findById(batch.id()).orElseThrow().status())
                .isEqualTo(BatchStatus.RELEASED);
    }

    @Test
    void sameKeySameParamsReplaysFirstResult() {
